package com.guocheng.mediapocket;
import com.sun.net.httpserver.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.w3c.dom.*;
public class DlnaClientTest {
 static void check(boolean b,String msg){if(!b)throw new AssertionError(msg);}
 static void reply(HttpExchange e,int status,String xml)throws IOException{byte[] body=xml.getBytes(StandardCharsets.UTF_8);e.getResponseHeaders().set("Content-Type","text/xml; charset=utf-8");e.sendResponseHeaders(status,body.length);e.getResponseBody().write(body);e.close();}
 static String response(String action,String data){return "<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\"><s:Body><u:"+action+"Response xmlns:u=\""+DlnaClient.SERVICE+"\">"+data+"</u:"+action+"Response></s:Body></s:Envelope>";}
 public static void main(String[] args)throws Exception{try{run();}catch(Throwable e){e.printStackTrace();System.exit(1);}}
 static void run()throws Exception{
  HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);ExecutorService workers=Executors.newCachedThreadPool();server.setExecutor(workers);String base="http://127.0.0.1:"+server.getAddress().getPort();List<String> calls=Collections.synchronizedList(new ArrayList<>());AtomicReference<String> selectedUrl=new AtomicReference<>(),metadata=new AtomicReference<>();AtomicBoolean fault=new AtomicBoolean(),invalid=new AtomicBoolean();
  String descriptor="<root xmlns=\"urn:schemas-upnp-org:device-1-0\"><URLBase>"+base+"/root/</URLBase><device><deviceType>urn:schemas-upnp-org:device:MediaRenderer:1</deviceType><friendlyName>客厅 &amp; TV</friendlyName><UDN>uuid:test-tv</UDN><serviceList><service><serviceType>"+DlnaClient.SERVICE+"</serviceType><controlURL>/control</controlURL></service></serviceList></device></root>";
  server.createContext("/description",e->reply(e,200,descriptor));
  server.createContext("/control",e->{try{String header=e.getRequestHeaders().getFirst("SOAPAction");String action=header.substring(header.indexOf('#')+1).replace("\"","");calls.add(action);String request=DlnaClient.read(e.getRequestBody(),256*1024);Document doc=DlnaClient.xml(request);check(DlnaClient.first(doc,"InstanceID").equals("0"),"InstanceID set");if(action.equals("SetAVTransportURI")){selectedUrl.set(DlnaClient.first(doc,"CurrentURI"));metadata.set(DlnaClient.first(doc,"CurrentURIMetaData"));}if(fault.get()){reply(e,500,"<s:Envelope xmlns:s=\"http://schemas.xmlsoap.org/soap/envelope/\"><s:Body><s:Fault><detail><UPnPError xmlns=\"urn:schemas-upnp-org:control-1-0\"><errorCode>714</errorCode><errorDescription>Illegal MIME-type</errorDescription></UPnPError></detail></s:Fault></s:Body></s:Envelope>");return;}if(invalid.get()){reply(e,200,"<html>login</html>");return;}reply(e,200,response(action,action.equals("GetTransportInfo")?"<CurrentTransportState>PLAYING</CurrentTransportState>":""));}catch(Throwable failure){failure.printStackTrace();e.close();}});
  server.start();DatagramSocket ssdp=new DatagramSocket(new InetSocketAddress("127.0.0.1",0));Thread responder=new Thread(()->{try{for(int i=0;i<2;i++){byte[] bytes=new byte[8192];DatagramPacket p=new DatagramPacket(bytes,bytes.length);ssdp.receive(p);String request=new String(bytes,0,p.getLength(),StandardCharsets.US_ASCII);check(request.startsWith("M-SEARCH * HTTP/1.1\r\n")&&request.contains("MAN: \"ssdp:discover\""),"real SSDP search sent");byte[] answer=("HTTP/1.1 200 OK\r\nLoCaTiOn: "+base+"/description\r\nUSN: uuid:test-tv::upnp:rootdevice\r\n\r\n").getBytes(StandardCharsets.UTF_8);ssdp.send(new DatagramPacket(answer,answer.length,p.getSocketAddress()));}}catch(SocketException ignored){}catch(Exception e){throw new RuntimeException(e);}},"fake-ssdp-renderer");responder.start();
  try{
   DlnaClient.Scan scan=new DlnaClient.Scan();List<DlnaClient.Device> found=scan.find(InetAddress.getByName("127.0.0.1"),new InetSocketAddress("127.0.0.1",ssdp.getLocalPort()),350);scan.close();check(found.size()==1,"duplicate SSDP responses dedup to one device");DlnaClient.Device tv=found.get(0);check(tv.name.equals("客厅 & TV")&&tv.control.toString().equals(base+"/control"),"real device descriptor parsed, root control URL resolved");
   String url="https://media.example/video.mp4?sig=a&b=1",title="影片 & <第1集>";DlnaClient.play(tv,url,title);check(calls.subList(0,2).equals(Arrays.asList("SetAVTransportURI","Play")),"URI assigned before Play");check(url.equals(selectedUrl.get()),"signed URI transmitted unchanged");Document didl=DlnaClient.xml(metadata.get());check(DlnaClient.first(didl,"title").equals(title)&&DlnaClient.first(didl,"res").equals(url),"DIDL/XML escaping round trips title and URL");check(DlnaClient.state(tv).equals("PLAYING"),"state read from device response");DlnaClient.control(tv,"Pause");DlnaClient.control(tv,"Stop");check(calls.contains("Pause")&&calls.contains("Stop"),"real pause/stop SOAP actions");
   calls.clear();fault.set(true);try{DlnaClient.play(tv,url,title);throw new AssertionError("fault must fail");}catch(IOException expected){check(expected.getMessage().contains("714"),"UPnP error surfaced");}check(calls.equals(Arrays.asList("SetAVTransportURI")),"failed URI does not send Play");fault.set(false);invalid.set(true);try{DlnaClient.control(tv,"Play");throw new AssertionError("HTTP 200 login page must fail");}catch(IOException expected){check(expected.getMessage().contains("应答"),"non-SOAP 200 not treated as playback success");}invalid.set(false);
   try{DlnaClient.descriptor(new URL(base+"/description"),descriptor.replace(">/control<",">http://8.8.8.8/control<"));throw new AssertionError("public control URL rejected");}catch(IOException expected){}
   try{DlnaClient.xml("<!DOCTYPE root [<!ENTITY x SYSTEM 'file:///etc/passwd'>]><root>&x;</root>");throw new AssertionError("external entity rejected");}catch(IOException expected){}
   DlnaClient.Scan cancelled=new DlnaClient.Scan();cancelled.close();try{cancelled.find(InetAddress.getLoopbackAddress(),100);throw new AssertionError("cancelled scan must fail");}catch(InterruptedIOException expected){}
   check(DlnaClient.headers("NOTIFY * HTTP/1.1\r\nLOCATION: "+base+"/description").isEmpty(),"notifications not mistaken for search response");
  }finally{ssdp.close();responder.join(1500);server.stop(0);workers.shutdownNow();}
  System.out.println("PASS: real UDP SSDP discovery, descriptor/dedup, SOAP URI/play/pause/stop/state, signed URL and DIDL escaping, SOAP faults, false-success rejection, local-device scope, XML entity rejection and scan cancellation.");
 }
}
